function cN(e, n) {
    if (e.length <= 1)
        return [...e];
    let t = e.map( (a, i) => i);
    for (let a = t.length - 1; a > 0; a--) {
        let i = Math.floor(Math.random() * (a + 1));
        [t[a],t[i]] = [t[i], t[a]]
    }
    let r = t.map(a => e[a]);
    return n && r[0]?.url === n && ([r[0],r[1]] = [r[1], r[0]]),
    r
}
